#[inline(never)]
#[target_feature(enable="avx512f,avx512bw,vpclmulqdq")]
unsafe fn xseed_three_impl<
    const LOW_OUTER: bool,
    const HIGH_ONE_OUTER: bool,
>(
    ptr: *mut F128,
    row_mask: usize,
    dense_lanes: usize,
    twiddles: &[F128; 7],
) {
    use core::arch::x86_64::*;
    const DIET: bool = true;
    const LOW_INNER: bool = true;
    const NNC: usize = 64;
    let num_ntts = 64;
    assert!(matches!(dense_lanes, 60 | 64));
    assert!(row_mask < 4);

    // Shape substitution (identity: the wrapper only pins the runtime value).
    let num_ntts = if NNC != 0 { NNC } else { num_ntts };
    debug_assert!(!HIGH_ONE_OUTER || twiddles[0].hi == 1);

    // SAFETY: caller provides target features and pointer geometry.
    unsafe {
        // Seven broadcasts (plus their x^64 companions under DIET) hoisted
        // out of the lane loop: 8 rows stay live in registers across all
        // three layers, so a row is loaded once and stored once for 12
        // butterflies instead of the fused-two + single-layer pair's two
        // loads and two stores for the same 12.
        let zero = _mm512_setzero_si512();
        let mut tw = [(zero, zero); 7];
        // The high-one product needs only the original twiddle broadcast.
        tw[0] = if HIGH_ONE_OUTER {
            tw_x4::<false, false>(twiddles[0])
        } else {
            tw_x4::<LOW_OUTER, DIET>(twiddles[0])
        };
        for (slot, value) in tw[1..].iter_mut().zip(twiddles[1..].iter()) {
            *slot = tw_x4::<LOW_INNER, DIET>(*value);
        }
        let row = |i: usize| ptr.add(i * num_ntts);
        let source_row = |i: usize| ptr.add((i ^ row_mask) * num_ntts);
        let mut lane = 0;

        macro_rules! butterfly {
            ($values:ident, $u:expr, $v:expr, $twiddle:expr, $low:expr) => {{
                butterfly!($values, $u, $v, $twiddle, $low, false);
            }};
            ($values:ident, $u:expr, $v:expr, $twiddle:expr, $low:expr, $high_one:expr) => {{
                let product = if $high_one {
                    mul_x4_high_one($twiddle, $values[$v])
                } else {
                    mul_x4::<$low, DIET>($twiddle, $values[$v])
                };
                let new_u = _mm512_xor_si512($values[$u], product);
                $values[$v] = _mm512_xor_si512($values[$v], new_u);
                $values[$u] = new_u;
            }};
        }
        // Two lane chunks per iteration: 16 live row registers + 14 twiddle
        // registers still fit the 32 zmm file, and doubling the independent
        // butterflies per layer (4 -> 8) covers the CLMUL latency and doubles
        // the outstanding row misses.
        // Dense-loop butterfly with lazy x^64 folds (diet forms only): the
        // product's x^64-position half accumulates in `$m[$u]`, `v ^= u`
        // shares it, and it is folded when `$fold` (the row is a multiplicand
        // in the next layer, or this is the last layer). Eight folds per four
        // lanes instead of twelve; same field elements.
        macro_rules! lazy_butterfly {
            ($p:expr, $m:expr, $u:expr, $v:expr, $twiddle:expr, $low:expr, $high_one:expr, $fold:expr) => {{
                if DIET {
                    let (lo, hi) = if $high_one {
                        mul_x4_high_one_parts($twiddle, $p[$v])
                    } else {
                        mul_x4_parts::<$low>($twiddle, $p[$v])
                    };
                    $m[$u] = _mm512_xor_si512($m[$u], hi);
                    let mut new_u = _mm512_xor_si512($p[$u], lo);
                    if $fold {
                        new_u = _mm512_xor_si512(new_u, fold_x64($m[$u]));
                        $m[$u] = zero;
                    }
                    $p[$v] = _mm512_xor_si512($p[$v], new_u);
                    $m[$v] = _mm512_xor_si512($m[$v], $m[$u]);
                    $p[$u] = new_u;
                } else {
                    let product = if $high_one {
                        mul_x4_high_one($twiddle, $p[$v])
                    } else {
                        mul_x4::<$low, DIET>($twiddle, $p[$v])
                    };
                    let new_u = _mm512_xor_si512($p[$u], product);
                    $p[$v] = _mm512_xor_si512($p[$v], new_u);
                    $p[$u] = new_u;
                }
            }};
        }

        while lane + 8 <= dense_lanes {
            let mut values = [[zero; 8]; 2];
            for (c, chunk) in values.iter_mut().enumerate() {
                for (i, value) in chunk.iter_mut().enumerate() {
                    *value = _mm512_loadu_si512(source_row(i).add(lane + 4 * c) as *const __m512i);
                }
            }

            let outer = tw[0];
            let mut pending = [[zero; 8]; 2];
            for i in 0..4 {
                for c in 0..2 {
                    lazy_butterfly!(
                        values[c],
                        pending[c],
                        i,
                        i + 4,
                        outer,
                        LOW_OUTER,
                        HIGH_ONE_OUTER,
                        i & 2 != 0
                    );
                }
            }
            for s in 0..2 {
                let twiddle = tw[1 + s];
                for i in 0..2 {
                    for c in 0..2 {
                        lazy_butterfly!(
                            values[c],
                            pending[c],
                            4 * s + i,
                            4 * s + i + 2,
                            twiddle,
                            LOW_INNER,
                            false,
                            i & 1 != 0
                        );
                    }
                }
            }
            for s in 0..4 {
                for c in 0..2 {
                    lazy_butterfly!(
                        values[c],
                        pending[c],
                        2 * s,
                        2 * s + 1,
                        tw[3 + s],
                        LOW_INNER,
                        false,
                        true
                    );
                }
            }

            for (c, chunk) in values.iter().enumerate() {
                for (i, value) in chunk.iter().enumerate() {
                    _mm512_storeu_si512(row(i).add(lane + 4 * c) as *mut __m512i, *value);
                }
            }
            lane += 8;
        }
        while lane + 4 <= dense_lanes {
            let mut values = [zero; 8];
            for (i, value) in values.iter_mut().enumerate() {
                *value = _mm512_loadu_si512(source_row(i).add(lane) as *const __m512i);
            }

            let outer = tw[0];
            let mut pending = [zero; 8];
            for i in 0..4 {
                lazy_butterfly!(
                    values,
                    pending,
                    i,
                    i + 4,
                    outer,
                    LOW_OUTER,
                    HIGH_ONE_OUTER,
                    i & 2 != 0
                );
            }
            for s in 0..2 {
                let twiddle = tw[1 + s];
                for i in 0..2 {
                    lazy_butterfly!(
                        values,
                        pending,
                        4 * s + i,
                        4 * s + i + 2,
                        twiddle,
                        LOW_INNER,
                        false,
                        i & 1 != 0
                    );
                }
            }
            for s in 0..4 {
                lazy_butterfly!(
                    values,
                    pending,
                    2 * s,
                    2 * s + 1,
                    tw[3 + s],
                    LOW_INNER,
                    false,
                    true
                );
            }

            for (i, value) in values.iter().enumerate() {
                _mm512_storeu_si512(row(i).add(lane) as *mut __m512i, *value);
            }
            lane += 4;
        }
        // Mixed group straddling `dense_lanes` (ranked: lanes 56..59 with
        // dense_lanes = 57): one vector group instead of eight portable
        // scalar lanes. Same butterflies, same twiddles, same values.
        if NNC != 0 && lane < dense_lanes && lane + 4 <= num_ntts && !masked_tail_disabled() {
            // Rows 1, 3, 5, 7 are zero on lanes `dense_lanes..`: load them
            // masked, so the dense network sees exactly the true inputs.
            let odd_mask: __mmask8 = ((1u32 << (2 * (dense_lanes - lane))) - 1) as __mmask8;
            let mut values = [zero; 8];
            for (i, value) in values.iter_mut().enumerate() {
                *value = if i & 1 == 0 {
                    _mm512_loadu_si512(source_row(i).add(lane) as *const __m512i)
                } else {
                    _mm512_maskz_loadu_epi64(odd_mask, source_row(i).add(lane) as *const i64)
                };
            }

            let outer = tw[0];
            let mut pending = [zero; 8];
            for i in 0..4 {
                lazy_butterfly!(
                    values,
                    pending,
                    i,
                    i + 4,
                    outer,
                    LOW_OUTER,
                    HIGH_ONE_OUTER,
                    i & 2 != 0
                );
            }
            for s in 0..2 {
                let twiddle = tw[1 + s];
                for i in 0..2 {
                    lazy_butterfly!(
                        values,
                        pending,
                        4 * s + i,
                        4 * s + i + 2,
                        twiddle,
                        LOW_INNER,
                        false,
                        i & 1 != 0
                    );
                }
            }
            for s in 0..4 {
                lazy_butterfly!(
                    values,
                    pending,
                    2 * s,
                    2 * s + 1,
                    tw[3 + s],
                    LOW_INNER,
                    false,
                    true
                );
            }

            for (i, value) in values.iter().enumerate() {
                _mm512_storeu_si512(row(i).add(lane) as *mut __m512i, *value);
            }
            lane += 4;
        }
        // Published zero tail: rows 1, 3, 5, 7 are zero here, so only the
        // four even rows are read and the deepest layer is a copy.
        while lane + 4 <= num_ntts {
            let mut values = [zero; 8];
            for i in 0..4 {
                values[2 * i] = _mm512_loadu_si512(source_row(2 * i).add(lane) as *const __m512i);
            }
            let outer = tw[0];
            butterfly!(values, 0, 4, outer, LOW_OUTER, HIGH_ONE_OUTER);
            butterfly!(values, 2, 6, outer, LOW_OUTER, HIGH_ONE_OUTER);
            butterfly!(values, 0, 2, tw[1], LOW_INNER);
            butterfly!(values, 4, 6, tw[2], LOW_INNER);
            for i in 0..4 {
                let v = values[2 * i];
                _mm512_storeu_si512(row(2 * i).add(lane) as *mut __m512i, v);
                _mm512_storeu_si512(row(2 * i + 1).add(lane) as *mut __m512i, v);
            }
            lane += 4;
        }

    }
}


/// Exact row permutation confined to each quartet. It is its own inverse.
#[inline(always)]
fn xseed_physical_row(row: usize) -> usize {
    row ^ (((row >> 3) ^ (row >> 7)) & 3)
}

/// Transform exclusively owned logical r groups in a banked deep block.
/// The pointer is the block's physical base; origin is its logical row index.
#[target_feature(enable="avx512f,avx512bw,vpclmulqdq")]
pub(crate) unsafe fn xseed_four_rows(
    ptr: *mut F128, origin: usize, sixteenth: usize, r0: usize, r1: usize,
    t: &[F128; 15], odd_tail: usize, raw7: bool, hint: u8,
) { unsafe {
    assert!(matches!(sixteenth,8|128) && r0 <= r1 && r1 <= sixteenth);
    assert!(origin.is_multiple_of(16*sixteenth));
    assert!(matches!(odd_tail,0|4));
    assert!(!raw7 || (sixteenth==8 && r0==0 && r1==8 && odd_tail==4));
    let p = prepare_four(t).expect("banked layout requires prepared kernels");
    let ordered = super::super::ntt_alias_load_order_enabled();
    macro_rules! run {($s:expr) => {
        match (hint,ordered) {
            (0,false) => xseed_four_rows_impl::<$s,0,0>(ptr,origin,r0,r1,&p,odd_tail,raw7),
            (0,true) => xseed_four_rows_impl::<$s,0,1>(ptr,origin,r0,r1,&p,odd_tail,raw7),
            (1,false) => xseed_four_rows_impl::<$s,1,0>(ptr,origin,r0,r1,&p,odd_tail,raw7),
            (1,true) => xseed_four_rows_impl::<$s,1,1>(ptr,origin,r0,r1,&p,odd_tail,raw7),
            (_,false) => xseed_four_rows_impl::<$s,2,0>(ptr,origin,r0,r1,&p,odd_tail,raw7),
            (_,true) => xseed_four_rows_impl::<$s,2,1>(ptr,origin,r0,r1,&p,odd_tail,raw7),
        }
    }}
    if sixteenth==8 { run!(8); } else { run!(128); }
}}

#[inline(never)]
#[target_feature(enable="avx512f,avx512bw,vpclmulqdq")]
unsafe fn xseed_four_rows_impl<const S16:usize,const H:u8,const ORD:u8>(
    ptr:*mut F128,origin:usize,r0:usize,r1:usize,p:&PreparedFour,odd_tail:usize,raw7:bool,
) { unsafe {
    #[repr(C,align(64))] struct Tail([F128;64]);
    let mut storage=core::mem::MaybeUninit::<Tail>::uninit();
    let tail=storage.as_mut_ptr().cast::<F128>();
    let lead=(p.prefetch_lines*4).min(64);
    let row=|r:usize|ptr.add((xseed_physical_row(origin+r)-origin)*64);
    for r in r0..r1 {
        let odd=r&1!=0;
        let lanes=if odd {if raw7 {56} else {64-odd_tail}} else {64};
        let bank=core::array::from_fn(|b|row(r+b*S16));
        // Same physical rolling lead as the incumbent. Hints may cross into
        // another physical row at the end; they never participate in values.
        let prefetch=bank.map(|p|p.add(lead) as *const F128);
        if H==0 || r+1==S16 {xseed_four_banks::<S16,0,ORD>(bank,p,lanes*16,prefetch);}
        else {xseed_four_banks::<S16,H,ORD>(bank,p,lanes*16,prefetch);}
        if raw7 && odd {
            for i in 0..16 {tail.add(i*4+(r>>1)).write(row(i*S16+r).add(56).read());}
        }
    }
    if raw7 {
        butterfly_four_fixed_registers::<1,4,0,0>(tail,p,64,tail);
        for i in 0..16 {for j in 0..4 {row(i*S16+2*j+1).add(56).write(tail.add(i*4+j).read());}}
    }
}}

/// Final-three reads the permutation and writes canonical rows in the same
/// stores as the crown. Each vector chunk loads all rows before any store.
#[target_feature(enable="avx512f,avx512bw,vpclmulqdq")]
pub(crate) unsafe fn xseed_three_rows(ptr:*mut F128,origin:usize,dense:usize,t:&[F128;7]) { unsafe {
    assert!(origin.is_multiple_of(8));
    assert!(t[1..].iter().all(|v|v.hi==0));
    let mask=((origin>>3)^(origin>>7))&3;
    if t[0].hi==0 {xseed_three_impl::<true,false>(ptr,mask,dense,t);}
    else if t[0].hi==1 {xseed_three_impl::<false,true>(ptr,mask,dense,t);}
    else {xseed_three_impl::<false,false>(ptr,mask,dense,t);}
}}
